import re

def parse_jobs(text: str) -> list[dict]:
    jobs = []
    job_pattern = r'Job ID: (\d+), Title: (.+?), Location: (.+?)\n(.+?)(?=\n\n|$)'
    matches = re.findall(job_pattern, text, re.DOTALL)

    for match in matches:
        job_id, title, location, details = match
        job_details = {}
        detail_lines = details.strip().split('\n')
        for line in detail_lines:
            key, value = line.split(': ', 1)
            job_details[key] = value
        jobs.append({
            'id': int(job_id),
            'title': title,
            'location': location,
            'details': job_details
        })

    return jobs

