def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'
    binary = ''
    is_negative = n < 0
    n = abs(n)
    while n > 0:
        binary = str(n % 2) + binary
        n //= 2
    if is_negative:
        binary = '-' + binary
    return binary

