def flatten_list(nested: list) -> list:
    flattened = []
    queue = deque([nested])

    while queue:
        current = queue.popleft()
        if isinstance(current, list):
            for item in reversed(current):
                queue.appendleft(item)
        else:
            flattened.append(current)

    return flattened
