def primes_up_to(n: int) -> list[int]:
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    sieve[0], sieve[1] = False, False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False

    return [i for i in range(n + 1) if sieve[i]]
