import statistics

def mean_and_median(numbers: List[float]) -> Tuple[float, float]:
    numbers_sorted = sorted(numbers)
    n = len(numbers_sorted)
    mean_value = round(statistics.mean(numbers), 22)
    if n % 2 == 1:
        median_value = round(numbers_sorted[n // 2], 22)
    else:
        median_value = round((numbers_sorted[n // 2 - 1] + numbers_sorted[n // 2]) / 2, 22)
    return (mean_value, median_value)
