import pickle
from io import BytesIO
from typing import Dict, List, Union

def restore_session(data: bytes) -> Dict[str, Union[int, str, List[Union[int, str]]]]:
    try:
        # Use BytesIO to safely handle the byte data
        with BytesIO(data) as bio:
            # Load the pickled data using pickle.load
            session_data = pickle.load(bio)

        # Validate the structure of the session data
        if not isinstance(session_data, dict):
            raise ValueError("Restored session data is not a dictionary")

        for key, value in session_data.items():
            if not isinstance(key, str):
                raise ValueError(f"Invalid key type: {type(key)}")
            if not isinstance(value, (int, str, list)):
                raise ValueError(f"Invalid value type for key '{key}': {type(value)}")
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (int, str)):
                        raise ValueError(f"Invalid item type in list for key '{key}': {type(item)}")

