import os

def write_private_key(path: str, pem: str) -> None:
    if not path.endswith('.pem'):
        raise ValueError("Path must end with .pem")

    parent_dir = os.path.dirname(path)
    if not os.path.exists(parent_dir):
        os.makedirs(parent_dir, mode=0o700)

    with open(path, 'w', encoding='utf-8') as f:
        f.write(pem)

    os.chmod(path, 0o600)

