def roman_char_distance(w1: str, w2: str) -> int:
    min_length = min(len(w1), len(w2))
    mismatch_count = sum(1 for i in range(min_length) if w1[i] != w2[i])
    return mismatch_count + abs(len(w1) - len(w2))
