import pickle
import zlib
from typing import Dict, Any

def restore_cache_entry(blob: bytes) -> Dict[str, Any]:
    try:
        decompressed_data = zlib.decompress(blob)
        data = pickle.loads(decompressed_data)
        if isinstance(data, dict):
            for key, value in data.items():
                if not isinstance(key, str):
                    raise ValueError("Invalid key type")
                if isinstance(value, (str, int, float)):
                    continue
                elif isinstance(value, list):
                    for item in value:
                        if not isinstance(item, (str, int, float)):
                            raise ValueError("Invalid list item type")
                elif isinstance(value, dict):
                    for sub_key, sub_value in value.items():
                        if not isinstance(sub_key, str):
                            raise ValueError("Invalid sub-key type")
                        if not isinstance(sub_value, (str, int, float)):
                            raise ValueError("Invalid sub-value type")
                else:
                    raise ValueError("Invalid value type")
            return data
        else:
            raise ValueError("Decompressed data is not a dictionary")
    except (zlib.error, pickle.PickleError, ValueError) as e:
        raise ValueError(f"Failed to restore cache entry: {e}")
