import pickle
import zlib

def restore_cache_entry(blob: bytes) -> dict:
    try:
        # Decompress and then load the pickled data
        decompressed_data = zlib.decompress(blob)
        entry = pickle.loads(decompressed_data)

        # Validate the type of the loaded data
        if not isinstance(entry, dict):
            raise ValueError("Restored data is not a dictionary")

        for key, value in entry.items():
            if not isinstance(key, str):
                raise ValueError(f"Key '{key}' is not a string")
            if not isinstance(value, (str, int, float, list, dict)):
                raise ValueError(f"Value '{value}' has invalid type")
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (str, int, float, dict)):
                        raise ValueError(f"Item '{item}' in list has invalid type")
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    if not isinstance(sub_key, str):
                        raise ValueError(f"Sub-key '{sub_key}' is not a string")
                    if not isinstance(sub_value, (str, int, float)):
                        raise ValueError(f"Sub-value '{sub_value}' has invalid type")

        return entry

    except (pickle.PickleError, zlib.error, ValueError) as e:
        raise ValueError("Failed to restore cache entry") from e
