from typing import Dict, List, Tuple

def evaluate_expression(expression: str) -> float:
    if not expression.strip():
        raise ValueError("Expression cannot be empty")

    tokens = []
    i = 0
    while i < len(expression):
        char = expression[i]
        if char.isdigit() or (char == '.' and i > 0 and expression[i - 1].isdigit()):
            j = i + 1
            while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            tokens.append(float(expression[i:j]))
            i = j
        elif char in "+-*/()":
            tokens.append(char)
            i += 1
        else:
            i += 1

    def apply_operator(operators: List[str], values: List[float]) -> None:
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(operator(left, right))
        elif operator == '-':
            values.append(operator(left, right))
        elif operator == '*':
            values.append(operator(left, right))
        elif operator == '/':
            values.append(operator(left, right))

    precedence: Dict[str, int] = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
    associativity: Dict[str, str] = {'+': 'L', '-': 'L', '*': 'L', '/': 'L', '**': 'R'}
    operators: List[str] = []
    values: List[float] = []

    for token in tokens:
        if isinstance(token, float):
            values.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()
        else:
            while (operators and operators[-1] != '(' and
                   ((precedence[operators[-1]] > precedence[token]) or
                    (precedence[operators[-1]] == precedence[token] and associativity[token] == 'L'))):
                apply_operator(operators, values)
            operators.append(token)

