OPERATORS = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv,
    '**': operator.pow,
}

def evaluate_expression(expression: str) -> float:
    def apply_operator(operators: List[str], values: List[float]) -> None:
        operator_ = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(OPERATORS[operator_](left, right))

    def greater_precedence(op1: str, op2: str) -> bool:
        return OPERATORS[op1].__name__ > OPERATORS[op2].__name__

    if not expression:
        raise ValueError("Empty expression")

    tokens = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        elif expression[i] in OPERATORS or expression[i] in "()":
            tokens.append(expression[i])
        else:
            j = i + 1
            while j < len(expression) and expression[j].isdigit():
                j += 1
            if '.' in expression[i:j]:
                tokens.append(float(expression[i:j]))
            else:
                tokens.append(int(expression[i:j]))
            i = j - 1
        i += 1

    values: List[float] = []
    operators: List[str] = []

    for token in tokens:
        if isinstance(token, int) or isinstance(token, float):
            values.append(token)
        elif token == '(':
