import os
from urllib.parse import unquote

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Remove leading '/' and decode URL
    request_path = unquote(request_path[1:])

    # Construct full file path
    file_path = os.path.join(web_root, request_path)

    # If path ends with '/', append 'index.html'
    if file_path.endswith('/'):
        file_path += 'index.html'

    # Check if file exists
    if os.path.isfile(file_path):
        try:
            with open(file_path, 'rb') as file:
                return 200, file.read()
        except Exception as e:
            return 500, f"Internal Server Error: {str(e)}".encode('utf-8')
    else:
        return 404, b"Not Found"
