import ast

def evaluate_expression(expression: str) -> float:
    try:
        # Remove optional spaces
        expression = expression.replace(" ", "")

        # Check for balanced parentheses
        if expression.count("(") != expression.count(")"):
            raise ValueError("Unbalanced parentheses")

        # Evaluate the expression using Python's AST module
        node = ast.parse(expression, mode='eval').body

        # Define a custom eval function to handle floating point numbers
        def custom_eval(node):
            if isinstance(node, ast.Num):  # <number>
                return node.n
            elif isinstance(node, ast.BinOp):  # <left> <operator> <right>
                left = custom_eval(node.left)
                right = custom_eval(node.right)
                if isinstance(node.op, ast.Add):
                    return left + right
                elif isinstance(node.op, ast.Sub):
                    return left - right
                elif isinstance(node.op, ast.Mult):
                    return left * right
                elif isinstance(node.op, ast.Div):
                    return left / right
                elif isinstance(node.op, ast.Pow):
                    return left ** right
            elif isinstance(node, ast.UnaryOp):  # <operator> <operand> e.g., -1
                operand = custom_eval(node.operand)
                if isinstance(node.op, ast.USub):
                    return -operand
            else:
                raise TypeError(node)

        result = custom_eval(node)
        return float(result)

    except (SyntaxError, ZeroDivisionError, TypeError) as e:
        raise ValueError(f"Invalid expression: {e}")
