import os

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Construct the full path to the requested file
    full_path = os.path.join(web_root, request_path.lstrip('/'))

    # Check if the path is within the web root to prevent directory traversal attacks
    if not full_path.startswith(web_root):
        return 403, b"Access Denied"

    # Check if the file exists and is a regular file
    if os.path.isfile(full_path):
        try:
            # Read the file content
            with open(full_path, 'rb') as file:
                body = file.read()
            return 200, body
        except IOError:
            return 500, b"Internal Server Error"
    else:
        return 404, b"Not Found"
