import re
from typing import Union

class SafeEval:
    def __init__(self):
        self.operations = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y if y != 0 else None,
            '**': lambda x, y: x ** y,
            '-u': lambda x: -x
        }

    def evaluate(self, expression: str) -> float:
        if not expression or not re.match(r'^[+-]?(\d+(\.\d*)?|\.\d+)(\s*[+\-*/\*\**]\s*[+-]?(\d+(\.\d*)?|\.\d+))*$', expression):
            raise ValueError("Invalid expression")

        tokens = re.findall(r'\b\d+\.\d+\b|\b\d+\b|[+\-*/\*\**()\-]', expression)
        stack = []
        operators = []

        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token == '-':
                if not operators or operators[-1] in '(*^/':
                    stack.append(-stack.pop())
                else:
                    operators.append('-')
            elif token in '+-*^/(':
                while (operators and operators[-1] != '(' and
                       ((token in '+-' and operators[-1] in '+-') or
                        (token in '*/' and operators[-1] in '*/'))):
                    b = stack.pop()
                    a = stack.pop()
                    op = operators.pop()
                    result = self.operations[op](a, b)
                    if result is None:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(result)
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = operators.pop()
                    result = self.operations[op](a, b)
                    if result is None:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(result)
                operators.pop()

        while operators:
            b = stack.pop()
            a = stack.pop()
            op = operators.pop()
            result = self.operations[op](a, b)
            if result is None:
                raise ZeroDivisionError("Division by zero")
            stack.append(result)

        return stack[0]

def evaluate_expression(expression: str) -> float:
    evaluator = SafeEval()
    try:
        return evaluator.evaluate(expression)
    except Exception as e:
        raise ValueError(f"Failed to evaluate expression: {str(e)}") from e
