import yaml

def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    try:
        jobs = yaml.safe_load(text)
        if not isinstance(jobs, list):
            raise ValueError("Parsed YAML is not a list")

        parsed_jobs = []
        for job in jobs:
            if not isinstance(job, dict):
                continue

            name = job.get('name')
            interval = job.get('interval')
            enabled = job.get('enabled', True)

            if name and isinstance(interval, int) and isinstance(enabled, bool):
                parsed_jobs.append({'name': name, 'interval': interval, 'enabled': enabled})

        return parsed_jobs

    except yaml.YAMLError as e:
        print(f"Error parsing YAML: {e}")
        return []
