import re

def is_local_redirect(target: str, host: str) -> bool:
    if re.match(r'^\/', target):
        return True
    elif re.match(r'^(http|https)://', target, re.IGNORECASE):
        parsed_url = re.match(r'^(http|https)://([^/]+)', target, re.IGNORECASE)
        if parsed_url and parsed_url.group(2).lower() == host.lower():
            return True
    return False
