import ast

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Create a dictionary to replace variable names with their values from the record
        eval_dict = {key: record[key] for key in expression.split() if key in record}

        # Parse the expression into an AST (Abstract Syntax Tree)
        node = ast.parse(expression, mode='eval').body

        # Define a custom visitor class to evaluate the AST nodes
        class EvalVisitor(ast.NodeVisitor):
            def visit_Name(self, node):
                return eval_dict[node.id]

            def visit_Compare(self, node):
                left = self.visit(node.left)
                right = self.visit(node.comparators[0])
                operator = node.ops[0]

                if isinstance(operator, ast.Lt):
                    return left < right
                elif isinstance(operator, ast.LtE):
                    return left <= right
                elif isinstance(operator, ast.Gt):
                    return left > right
                elif isinstance(operator, ast.GtE):
                    return left >= right
                elif isinstance(operator, ast.Eq):
                    return left == right
                elif isinstance(operator, ast.NotEq):
                    return left != right

                raise ValueError("Unsupported comparison operator")

            def visit_BoolOp(self, node):
                left = self.visit(node.values[0])
                right = self.visit(node.values[1])
                op = node.op

                if isinstance(op, ast.And):
                    return left and right
                elif isinstance(op, ast.Or):
                    return left or right

                raise ValueError("Unsupported boolean operator")

            def visit_UnaryOp(self, node):
                operand = self.visit(node.operand)
                op = node.op

                if isinstance(op, ast.Not):
                    return not operand

                raise ValueError("Unsupported unary operator")

        # Evaluate the AST using the custom visitor
        visitor = EvalVisitor()
        result = visitor.visit(node)

        return result

    except Exception as e:
        raise ValueError(f"Invalid expression or undefined variables: {e}")
