def is_local_redirect(target: str, host: str) -> bool:
    if not target or not host:
        return False

    # Check for invalid characters in target
    if any(ord(c) < 32 or ord(c) > 127 for c in target):
        return False

    # Check if target is a site-relative path
    if target.startswith('/'):
        return True

    # Check if target is an absolute URL
    url_pattern = re.compile(r'^(?:http|https)://')
    if url_pattern.match(target):
        parsed_url = re.match(url_pattern, target).group(0)
        target_host = target[len(parsed_url):].split('/')[0]
        return target_host.lower() == host.lower()

    return False
