    if not url.startswith(('http://', 'https://')):
        return False

    # Remove http:// or https:// from the beginning of the URL
    url = url[8:] if url.startswith('https://') else url[7:]

    # Check for user information in the URL
    if '@' in url:
        return False

    # Check for backslash, space, or control characters
    if any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Split the URL into host and path
    parts = url.split('/')
    host = parts[0]

    # Check if the host ends with a dot
    if host.endswith('.'):
        host = host[:-1]

    # Split the host by dots to check each label
    labels = host.split('.')
    if len(labels) < 2:
        return False
    for label in labels[:-1]:
        if not label.isalnum() or '-' in label:
            return False
    last_label = labels[-1]
    if not last_label.isalpha():
        return False

    # Check if the host is localhost or ends with .localhost
    if host == 'localhost' or host.endswith('.localhost'):
        return False

    # Check if port is present or is 443
    if ':' in host:
        port = host.split(':')[1]
        if not port.isdigit() or int(port) != 443:
