import re

def is_allowed_webhook(url: str) -> bool:
    # Remove any query parameters or fragments
    url = re.split(r'[?#]', url)[0]

    # Check if URL starts with https
    if not re.match(r'^https:', url, re.IGNORECASE):
        return False

    # Remove protocol part
    url = url[len('https://'):]

    # Check for user info in the URL
    if '@' in url:
        return False

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\x00-\x1F\x7F]', url):
        return False

    # Split by slashes to get the host and path
    parts = url.split('/')
    host = parts[0]

    # Check if the host ends with a dot
    if host.endswith('.'):
        return False

    # Split the host by dots to validate labels
    labels = host.split('.')
    if len(labels) < 2:
        return False

    for label in labels[:-1]:
        if not re.match(r'^[a-z0-9-]+$', label, re.IGNORECASE):
            return False

    last_label = labels[-1]
    if not re.match(r'^[a-z]+$', last_label, re.IGNORECASE):
        return False

    # Check if the host is localhost or ends with .localhost
    if re.match(r'^(localhost|\.localhost)$', host, re.IGNORECASE):
        return False

    # Check if port is present and is not 443
    if ':' in host:
        _, port = host.rsplit(':', 1)
        if not port.isdigit() or int(port) != 443:
            return False

    return True

