import operator

def matches_filter(expression: str, record: dict) -> bool:
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '%': operator.mod,
        '==': operator.eq,
        '!=': operator.ne,
        '<': operator.lt,
        '>': operator.gt,
        '<=': operator.le,
        '>=': operator.ge,
        'and': operator.and_,
        'or': operator.or_,
        'not': operator.not_
    }

    def safe_eval(expr):
        if expr.isdigit():
            return int(expr)
        elif expr in record:
            return record[expr]
        elif expr in operators:
            return operators[expr]
        else:
            raise ValueError(f"Undefined variable or operator: {expr}")

    try:
        return eval(expression, {"__builtins__": None}, {k: safe_eval(v) for k, v in record.items()})
    except Exception as e:
        raise ValueError("Invalid expression or undefined variable") from e
