import operator

def matches_filter(expression: str, record: dict) -> bool:
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '>': operator.gt,
        '<': operator.lt,
        '>=': operator.ge,
        '<=': operator.le,
        '==': operator.eq,
        '!=': operator.ne,
        'and': operator.and_,
        'or': operator.or_,
        'not': operator.not_
    }

    def safe_eval(expr):
        tokens = expr.split()
        stack = []

        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in operators:
                b = stack.pop()
                a = stack.pop()
                result = operators[token](a, b)
                stack.append(result)
            else:
                if token in record:
                    stack.append(record[token])
                else:
                    raise ValueError(f"Undefined variable: {token}")

        return stack[0]

    try:
        return safe_eval(expression)
    except Exception as e:
        raise ValueError("Invalid expression or undefined variable") from e
```

