    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            digits.append('-')
            n = (n // 3) + 1
        elif remainder == -1:
            digits.append('+')
            n = (n // 3) - 1
        else:
            digits.append(str(remainder))
            n //= 3

    # Reverse the list of digits to get the correct order
    digits.reverse()

    # Join the list into a single string
    result = ''.join(digits)

    return result

