import os
import subprocess

def make_tar(directory: str, archive_path: str) -> str:
    if not os.path.isdir(directory):
        raise ValueError(f"The directory {directory} does not exist.")
    if os.path.exists(archive_path):
        raise FileExistsError(f"The archive {archive_path} already exists.")

    base_name = os.path.basename(directory)
    subprocess.run(['tar', '-cvf', archive_path, '-C', os.path.dirname(directory), base_name], check=True)
    return archive_path

