import ast

class SafeEval(ast.NodeTransformer):
    def visit_BinOp(self, node):
        if isinstance(node.op, ast.Div) and isinstance(node.right, ast.Num) and node.right.n == 0:
            raise ZeroDivisionError("division by zero")
        return super().visit_BinOp(node)

def evaluate_expression(expression: str) -> float:
    try:
        parsed = ast.parse(expression, mode='eval')
        safe_eval = SafeEval()
        transformed = safe_eval.visit(parsed.body)
        result = eval(compile(transformed, filename="<ast>", mode="eval"))
        return float(result)
    except (SyntaxError, ValueError, ZeroDivisionError) as e:
        raise ValueError(f"Invalid expression: {e}")
