import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check for site-relative path
    if target.startswith('/') and '/' not in target[1:]:
        return True

    # Check for absolute URL with matching hostname
    url_pattern = re.compile(r'^(?:http|https)://([^/?#]+)')
    match = url_pattern.match(target)
    if match:
        redirect_host = match.group(1).lower()
        return redirect_host == host.lower()

    # Reject URLs with invalid characters
    if any(ord(char) < 32 or ord(char) > 127 for char in target):
        return False

    return False

