import ast

class FilterExpressionEvaluator(ast.NodeVisitor):
    def __init__(self, record):
        self.record = record

    def visit_Name(self, node):
        if node.id in self.record:
            return self.record[node.id]
        else:
            raise ValueError(f"Unknown variable: {node.id}")

    def visit_Num(self, node):
        return node.n

    def visit_Str(self, node):
        return node.s

    def visit_Compare(self, node):
        left = self.visit(node.left)
        right = self.visit(node.comparators[0])
        operator = node.ops[0]

        if isinstance(operator, ast.Gt):
            return left > right
        elif isinstance(operator, ast.Lt):
            return left < right
        elif isinstance(operator, ast.Ge):
            return left >= right
        elif isinstance(operator, ast.Le):
            return left <= right
        elif isinstance(operator, ast.Eq):
            return left == right
        elif isinstance(operator, ast.NotEq):
            return left != right
        else:
            raise ValueError(f"Unsupported operator: {operator}")

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        operator = node.op

        if isinstance(operator, ast.And):
            return left and right
        elif isinstance(operator, ast.Or):
            return left or right
        elif isinstance(operator, ast.Not):
            return not left
        else:
            raise ValueError(f"Unsupported operator: {operator}")

def matches_filter(expression: str, record: dict) -> bool:
