        # Check if the IP address is reserved for documentation
        if ip.is_reserved:
            return False

        # Check if the IP address is in the shared address space range
        if ip_str.startswith('100.64'):
            return False

        # Check if the IP address is an IPv4 broadcast address
        if ip.version == 4 and ip.is_broadcast:
            return False

        # Check if the IP address is an IPv4-mapped IPv6 address
        if ip.version == 6 and ip.is_ipv4_mapped:
            return False

        # If none of the above conditions are met, the IP address is public
        return True

    except ValueError:
        # Return False if the IP address is not valid
        return False
